// Store result in static data
const input = $input.first().json;
const body = input.body || input;

const jobId = body.job_id;
const result = body.result;

if (!jobId || !result) {
  return [{
    json: {
      success: false,
      error: 'job_id and result are required'
    }
  }];
}

// Store in global static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.results) {
  staticData.results = {};
}

staticData.results[jobId] = {
  ...result,
  storedAt: Date.now()
};

// Cleanup old results (>1 hour)
const oneHourAgo = Date.now() - (60 * 60 * 1000);
Object.keys(staticData.results).forEach(key => {
  if (staticData.results[key].storedAt < oneHourAgo) {
    delete staticData.results[key];
  }
});

return [{
  json: {
    success: true,
    job_id: jobId,
    stored: true
  }
}];

// Retrieve result from static data
const input = $input.first().json;
const query = input.query || {};

const jobId = query.job_id;

if (!jobId) {
  return [{
    json: {
      success: false,
      error: 'job_id query parameter is required'
    }
  }];
}

// Get from static data
const staticData = $getWorkflowStaticData('global');
const result = staticData.results?.[jobId];

if (!result) {
  return [{
    json: {
      success: false,
      found: false,
      job_id: jobId
    }
  }];
}

return [{
  json: {
    success: true,
    found: true,
    job_id: jobId,
    result: result
  }
}];
